# worker/tasks.py - Celery task for processing uploaded archive bundles
import os
import zipfile
import tempfile
import shutil
from celery import Celery
from pathlib import Path

app = Celery('archive_processor', broker='redis://redis:6379/0')

BASE_EXTRACT_DIR = '/var/lib/worker/extractions'
ALLOWED_EXTENSIONS = {'.csv', '.json', '.xml', '.txt', '.yaml', '.yml'}


def validate_archive_metadata(zip_path):
    """Validate archive metadata before extraction."""
    with zipfile.ZipFile(zip_path, 'r') as zf:
        for info in zf.infolist():
            # Check for excessively large files (zip bomb protection)
            if info.file_size > 100 * 1024 * 1024:  # 100MB limit
                raise ValueError(f"File too large: {info.filename}")
            # Check extension whitelist
            ext = Path(info.filename).suffix.lower()
            if ext and ext not in ALLOWED_EXTENSIONS:
                raise ValueError(f"Disallowed extension: {info.filename}")
    return True


def sanitize_filename(filename):
    """Remove null bytes and normalize unicode in filenames."""
    cleaned = filename.replace('\x00', '')
    # Normalize path separators
    cleaned = cleaned.replace('\\', '/')
    return cleaned


@app.task(bind=True, max_retries=3, default_retry_delay=60)
def process_archive(self, archive_path, job_id, requester_namespace='default'):
    """Process an uploaded zip archive for data ingestion pipeline.

    Archives are submitted via the ingestion-gateway service and routed
    to this worker for extraction and downstream processing.
    """
    extract_dir = os.path.join(BASE_EXTRACT_DIR, str(job_id))
    os.makedirs(extract_dir, exist_ok=True)

    try:
        validate_archive_metadata(archive_path)

        with zipfile.ZipFile(archive_path, 'r') as zf:
            for member in zf.infolist():
                if member.is_dir():
                    continue

                filename = sanitize_filename(member.filename)

                # Skip hidden files and __MACOSX artifacts
                if any(part.startswith('.') for part in filename.split('/')):
                    continue
                if '__MACOSX' in filename:
                    continue

                # Construct target path - NOTE: os.path.join with absolute
                # second arg returns just the second arg, but we use
                # string concatenation here to build the path
                target_path = os.path.join(extract_dir, filename)

                # Ensure parent directories exist
                os.makedirs(os.path.dirname(target_path), exist_ok=True)

                # Extract file
                with zf.open(member) as source:
                    with open(target_path, 'wb') as target:
                        shutil.copyfileobj(source, target)

        # Queue downstream processing
        extracted_files = []
        for root, dirs, files in os.walk(extract_dir):
            for f in files:
                extracted_files.append(os.path.join(root, f))

        return {
            'job_id': job_id,
            'status': 'completed',
            'files_extracted': len(extracted_files),
            'extract_dir': extract_dir
        }

    except zipfile.BadZipFile:
        return {'job_id': job_id, 'status': 'failed', 'error': 'Invalid archive'}
    except ValueError as e:
        return {'job_id': job_id, 'status': 'failed', 'error': str(e)}
    except Exception as exc:
        self.retry(exc=exc)


@app.task
def cleanup_extraction(job_id):
    """Remove extracted files after processing window expires."""
    extract_dir = os.path.join(BASE_EXTRACT_DIR, str(job_id))
    if os.path.exists(extract_dir):
        shutil.rmtree(extract_dir)
    return {'job_id': job_id, 'status': 'cleaned'}
